20	fn get_override_props(property: &str) -> Vec<&str> {
21	    let longhand_sub_props = get_longhand_sub_properties(property);
22	    let reset_to_initial_props = get_reset_to_initial_properties(property);
23	
24	    let mut merged = Vec::with_capacity(longhand_sub_props.len() + reset_to_initial_props.len());
25	
26	    let (mut i, mut j) = (0, 0);
27	
28	    while i < longhand_sub_props.len() && j < reset_to_initial_props.len() {
29	        if longhand_sub_props[i] < reset_to_initial_props[j] {
30	            merged.push(longhand_sub_props[i]);
31	            i += 1;
32	        } else {
33	            merged.push(reset_to_initial_props[j]);
34	            j += 1;
35	        }
36	    }
37	
38	    if i < longhand_sub_props.len() {
39	        merged.extend_from_slice(&longhand_sub_props[i..]);
40	    }
41	
42	    if j < reset_to_initial_props.len() {
43	        merged.extend_from_slice(&reset_to_initial_props[j..]);
44	    }
45	
46	    merged
47	}
