49	declare_lint_rule! {
50	    /// Disallow shorthand properties that override related longhand properties.
51	    ///
52	    /// For details on shorthand properties, see the [MDN web docs](https://developer.mozilla.org/en-US/docs/Web/CSS/Shorthand_properties).
53	    ///
54	    /// ## Examples
55	    ///
56	    /// ### Invalid
57	    ///
58	    /// ```css,expect_diagnostic
59	    /// a { padding-left: 10px; padding: 20px; }
60	    /// ```
61	    ///
62	    /// ### Valid
63	    ///
64	    /// ```css
65	    /// a { padding: 10px; padding-left: 20px; }
66	    /// ```
67	    ///
68	    /// ```css
69	    /// a { transition-property: opacity; } a { transition: opacity 1s linear; }
70	    /// ```
71	    ///
72	    pub NoShorthandPropertyOverrides {
73	        version: "1.8.2",
74	        name: "noShorthandPropertyOverrides",
75	        language: "css",
76	        recommended: true,
77	        severity: Severity::Error,
78	        sources: &[RuleSource::Stylelint("declaration-block-no-shorthand-property-overrides").same()],
79	    }
80	}
