82	#[derive(Default)]
83	struct PriorProperty {
84	    original: Box<str>,
85	    lowercase: Box<str>,
86	}
87	
88	#[derive(Default)]
89	struct NoDeclarationBlockShorthandPropertyOverridesVisitor {
90	    prior_props_in_block: Vec<PriorProperty>,
91	}
92	
93	impl Visitor for NoDeclarationBlockShorthandPropertyOverridesVisitor {
94	    type Language = CssLanguage;
95	
96	    fn visit(
97	        &mut self,
98	        event: &WalkEvent<SyntaxNode<Self::Language>>,
99	        mut ctx: VisitorContext<Self::Language>,
100	    ) {
101	        if let WalkEvent::Enter(node) = event {
102	            match node.kind() {
103	                CssSyntaxKind::CSS_DECLARATION_OR_RULE_BLOCK => {
104	                    self.prior_props_in_block.clear();
105	                }
106	                CssSyntaxKind::CSS_GENERIC_PROPERTY => {
107	                    if let Some(prop_node) = CssGenericProperty::cast_ref(node)
108	                        .and_then(|property_node| property_node.name().ok())
109	                    {
110	                        let prop = prop_node.to_trimmed_text();
111	                        #[expect(clippy::disallowed_methods)]
112	                        let prop_lowercase = prop.to_lowercase();
113	
114	                        let prop_prefix = vender_prefix(&prop_lowercase);
115	                        let unprefixed_prop = remove_vendor_prefix(&prop_lowercase, prop_prefix);
116	                        let override_props = get_override_props(unprefixed_prop);
117	
118	                        self.prior_props_in_block.iter().for_each(|prior_prop| {
119	                            let prior_prop_prefix = vender_prefix(&prior_prop.lowercase);
120	                            let unprefixed_prior_prop =
121	                                remove_vendor_prefix(&prior_prop.lowercase, prior_prop_prefix);
122	
123	                            if prop_prefix == prior_prop_prefix
124	                                && override_props.binary_search(&unprefixed_prior_prop).is_ok()
125	                            {
126	                                ctx.match_query(
127	                                    NoDeclarationBlockShorthandPropertyOverridesQuery {
128	                                        property_node: prop_node.clone(),
129	                                        override_property: prior_prop.original.clone(),
130	                                    },
131	                                );
132	                            }
133	                        });
134	
135	                        self.prior_props_in_block.push(PriorProperty {
136	                            original: prop.into(),
137	                            lowercase: prop_lowercase.into(),
138	                        });
139	                    }
140	                }
141	                _ => {}
142	            }
143	        }
144	    }
145	}
