12	declare_lint_rule! {
13	    /// Disallow the usage of specified root types
14	    ///
15	    /// Prevent the usage of certain root types (e.g. `mutation` and/or `subscription`)
16	    ///
17	    /// ## Examples
18	    ///
19	    /// ### Invalid
20	    ///
21	    /// ```json,options
22	    /// {
23	    ///   "options": {
24	    ///     "disallow": ["mutation"]
25	    ///   }
26	    /// }
27	    /// ```
28	    ///
29	    /// ```graphql,expect_diagnostic,use_options
30	    /// type Mutation {
31	    ///   createUser(input: CreateUserInput!): User!
32	    /// }
33	    /// ```
34	    ///
35	    /// ### Valid
36	    ///
37	    /// ```graphql,use_options
38	    /// type Query {
39	    ///   users: [User!]!
40	    /// }
41	    /// ```
42	    ///
43	    /// ## Options
44	    ///
45	    /// ### `disallow`
46	    ///
47	    /// This required option lists all disallowed root types (e.g. `mutation` and/or `subscription`).
48	    /// The values of the list are case-insensitive.
49	    ///
50	    /// Default `[]`
51	    ///
52	    /// ```json,options
53	    /// {
54	    ///   "options": {
55	    ///     "disallow": ["subscription"]
56	    ///   }
57	    /// }
58	    /// ```
59	    ///
60	    /// ```graphql,expect_diagnostic,use_options
61	    /// type Subscription {
62	    ///   user: User
63	    /// }
64	    /// ```
65	    ///
66	    pub NoRootType {
67	        version: "2.3.12",
68	        name: "noRootType",
69	        language: "graphql",
70	        recommended: false,
71	        sources: &[RuleSource::EslintGraphql("no-root-type").same()],
72	    }
73	}
74	
75	impl Rule for NoRootType {
76	    type Query = Ast<AnyNoRootTypeQuery>;
77	    type State = (TokenText, TextRange);
78	    type Signals = Option<Self::State>;
79	    type Options = NoRootTypeOptions;
80	
81	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
82	        let node = ctx.query();
83	        let root_types = &ctx.options().disallow;
84	
85	        if root_types.is_empty() {
86	            return None;
87	        }
88	
89	        match node {
90	            AnyNoRootTypeQuery::GraphqlObjectTypeDefinition(type_def) => {
91	                let name = type_def.name().ok()?;
92	                let value_token = name.value_token().ok()?;
93	                check_name(root_types, value_token)
94	            }
95	            AnyNoRootTypeQuery::GraphqlObjectTypeExtension(type_ext) => {
96	                let name = type_ext.name().ok()?;
97	                let value_token = name.value_token().ok()?;
98	                check_name(root_types, value_token)
99	            }
100	        }
101	    }
102	
103	    fn diagnostic(_ctx: &RuleContext<Self>, (name, range): &Self::State) -> Option<RuleDiagnostic> {
104	        Some(
105	            RuleDiagnostic::new(
106	                rule_category!(),
107	                range,
108	                markup! {
109	                    "The root type "{{name.to_string()}}" is forbidden."
110	                },
111	            )
112	            .note(markup! {
113	                "It's forbidden to use this root type within this project. Rework to use a different root type."
114	            }),
115	        )
116	    }
117	}
118	
119	declare_node_union! {
120	    pub AnyNoRootTypeQuery = GraphqlObjectTypeDefinition | GraphqlObjectTypeExtension
121	}
122	
123	fn check_name(
124	    root_types: &Vec<String>,
125	    name: SyntaxToken<GraphqlLanguage>,
126	) -> Option<(TokenText, TextRange)> {
127	    let trimmed = name.token_text_trimmed();
128	
129	    for root_type in root_types {
130	        if root_type.to_lowercase_cow() == trimmed.to_lowercase_cow() {
131	            return Some((trimmed, name.text_range()));
132	        }
133	    }
134	
135	    None
136	}
