13	declare_lint_rule! {
14	    /// Enforce that the `autofocus` attribute is not used on elements.
15	    ///
16	    /// Autofocusing elements can cause usability issues for sighted and non-sighted users, alike.
17	    /// However, the `autofocus` attribute is allowed on elements inside a `dialog` element or
18	    /// elements with a `popover` attribute, as these are modal contexts where autofocus is expected.
19	    ///
20	    /// ## Examples
21	    ///
22	    /// ### Invalid
23	    ///
24	    /// ```html,expect_diagnostic
25	    /// <input autofocus />
26	    /// ```
27	    ///
28	    /// ```html,expect_diagnostic
29	    /// <input autofocus="true" />
30	    /// ```
31	    ///
32	    /// ```html,expect_diagnostic
33	    /// <textarea autofocus>content</textarea>
34	    /// ```
35	    ///
36	    /// ### Valid
37	    ///
38	    /// ```html
39	    /// <input />
40	    /// ```
41	    ///
42	    /// ```html
43	    /// <div popover><input autofocus /></div>
44	    /// ```
45	    ///
46	    /// ```html
47	    /// <dialog><input autofocus /></dialog>
48	    /// ```
49	    ///
50	    /// ## Resources
51	    ///
52	    /// - [WHATWG HTML Standard, The autofocus attribute](https://html.spec.whatwg.org/multipage/interaction.html#attr-fe-autofocus)
53	    /// - [The accessibility of HTML 5 autofocus](https://brucelawson.co.uk/2009/the-accessibility-of-html-5-autofocus/)
54	    /// - [MDN Web Docs, HTMLElement: autofocus property](https://developer.mozilla.org/en-US/docs/Web/API/HTMLElement/autofocus)
55	    ///
56	    pub NoAutofocus {
57	        version: "2.4.0",
58	        name: "noAutofocus",
59	        language: "html",
60	        sources: &[RuleSource::EslintJsxA11y("no-autofocus").same()],
61	        recommended: true,
62	        severity: Severity::Error,
63	        fix_kind: FixKind::Unsafe,
64	    }
65	}
