67	impl Rule for NoAutofocus {
68	    type Query = Ast<HtmlAttribute>;
69	    type State = ();
70	    type Signals = Option<Self::State>;
71	    type Options = NoAutofocusOptions;
72	
73	    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
74	        let node = ctx.query();
75	
76	        // Check if this is an autofocus attribute
77	        if !is_autofocus_attribute(node) {
78	            return None;
79	        }
80	
81	        // Check if element is inside a dialog or has popover attribute in ancestors
82	        if is_inside_allowed_context(node).unwrap_or(false) {
83	            return None;
84	        }
85	
86	        Some(())
87	    }
88	
89	    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
90	        let node = ctx.query();
91	        Some(RuleDiagnostic::new(
92	            rule_category!(),
93	            node.syntax().text_trimmed_range(),
94	            markup! {
95	                "Avoid the "<Emphasis>"autofocus"</Emphasis>" attribute."
96	            },
97	        ))
98	    }
99	
100	    fn action(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<HtmlRuleAction> {
101	        let node = ctx.query();
102	        let mut mutation = ctx.root().begin();
103	        mutation.remove_node(node.clone());
104	        Some(HtmlRuleAction::new(
105	            ctx.metadata().action_category(ctx.category(), ctx.group()),
106	            ctx.metadata().applicability(),
107	            markup! { "Remove the "<Emphasis>"autofocus"</Emphasis>" attribute." }.to_owned(),
108	            mutation,
109	        ))
110	    }
111	}
