113	/// Check if the attribute is an autofocus attribute
114	fn is_autofocus_attribute(node: &HtmlAttribute) -> bool {
115	    node.name().is_ok_and(|name| {
116	        name.value_token()
117	            .is_ok_and(|value_token| value_token.text_trimmed().eq_ignore_ascii_case("autofocus"))
118	    })
119	}
120	
121	/// Check if the element is inside an allowed context (dialog or popover)
122	///
123	/// Note: We skip the first [HtmlElement] (the one containing the autofocus attribute)
124	/// because we only want to check if it's *inside* a dialog/popover, not if
125	/// it *is* the dialog/popover itself.
126	fn is_inside_allowed_context(attr: &HtmlAttribute) -> Option<bool> {
127	    let mut skip_first_element = true;
128	
129	    // Walk up the ancestors to find if we're inside a dialog or popover
130	    for ancestor in attr.syntax().ancestors().skip(1) {
131	        let Some(tag_element) = get_tag_element(&ancestor) else {
132	            continue;
133	        };
134	
135	        if skip_first_element {
136	            skip_first_element = false;
137	            continue;
138	        }
139	
140	        if is_dialog_or_popover(&tag_element) {
141	            return Some(true);
142	        }
143	    }
144	
145	    Some(false)
146	}
147	
148	/// Extract an [AnyHtmlTagElement] from an ancestor node
149	fn get_tag_element(node: &biome_html_syntax::HtmlSyntaxNode) -> Option<AnyHtmlTagElement> {
150	    HtmlElement::cast_ref(node)
151	        .and_then(|e| e.opening_element().ok())
152	        .map(AnyHtmlTagElement::from)
153	        .or_else(|| {
154	            HtmlSelfClosingElement::cast_ref(node).map(|e| AnyHtmlTagElement::from(e.clone()))
155	        })
156	}
157	
158	/// Check if the tag element is a dialog or has popover attribute
159	fn is_dialog_or_popover(tag_element: &AnyHtmlTagElement) -> bool {
160	    let is_dialog = tag_element
161	        .name()
162	        .ok()
163	        .and_then(|n| n.token_text_trimmed())
164	        .is_some_and(|text| text.eq_ignore_ascii_case("dialog"));
165	
166	    is_dialog || tag_element.find_attribute_by_name("popover").is_some()
