impl Rule for NoRootType {
    type Query = Ast<AnyNoRootTypeQuery>;
    type State = (TokenText, TextRange);
    type Signals = Option<Self::State>;
    type Options = NoRootTypeOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();
